--
-- Table structure for table `drivercertification`
--

DROP TABLE IF EXISTS `drivercertification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `drivercertification` (
  `DriverCertificationID` int NOT NULL AUTO_INCREMENT,
  `DriverID` int NOT NULL,
  `CertificationID` int NOT NULL,
  `IssueDate` date NOT NULL,
  `ExpiryDate` date NOT NULL,
  `Status` enum('Valid','Expired','Suspended') DEFAULT 'Valid',
  PRIMARY KEY (`DriverCertificationID`),
  UNIQUE KEY `UQ_Driver_Cert` (`DriverID`,`CertificationID`),
  KEY `FK_DriverCert_Certification` (`CertificationID`),
  CONSTRAINT `FK_DriverCert_Certification` FOREIGN KEY (`CertificationID`) REFERENCES `certification` (`CertificationID`),
  CONSTRAINT `FK_DriverCert_Driver` FOREIGN KEY (`DriverID`) REFERENCES `driver` (`DriverID`),
  CONSTRAINT `drivercertification_chk_1` CHECK ((`ExpiryDate` > `IssueDate`))
) ENGINE=InnoDB AUTO_INCREMENT=4577 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

