DROP TABLE IF EXISTS `driversafetyscore`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `driversafetyscore` (
  `ScoreID` int NOT NULL AUTO_INCREMENT,
  `DriverID` int NOT NULL,
  `ScoreMonth` int NOT NULL,
  `ScoreYear` int NOT NULL,
  `StartingScore` decimal(5,2) DEFAULT '100.00',
  `TotalPenalty` int DEFAULT '0',
  `HarshBrakingCount` int DEFAULT '0',
  `SpeedingCount` int DEFAULT '0',
  `FatigueWarningCount` int DEFAULT '0',
  `CriticalEventCount` int DEFAULT '0',
  `FinalScore` decimal(5,2) DEFAULT NULL,
  `RequiresCoaching` tinyint(1) DEFAULT '0',
  `AssignmentBlocked` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`ScoreID`),
  UNIQUE KEY `DriverID` (`DriverID`,`ScoreMonth`,`ScoreYear`),
  CONSTRAINT `FK_Score_Driver` FOREIGN KEY (`DriverID`) REFERENCES `driver` (`DriverID`)
) ENGINE=InnoDB AUTO_INCREMENT=3425 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
