--
-- Table structure for table `maintenancejob`
--

DROP TABLE IF EXISTS `maintenancejob`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `maintenancejob` (
  `JobID` int NOT NULL AUTO_INCREMENT,
  `VIN` varchar(17) NOT NULL,
  `WorkshopID` int NOT NULL,
  `AlertID` int DEFAULT NULL,
  `DateOpened` datetime NOT NULL,
  `DateClosed` datetime DEFAULT NULL,
  `DowntimeHours` decimal(6,2) DEFAULT '0.00',
  `TotalCostVND` decimal(15,2) DEFAULT '0.00',
  `JobStatus` enum('Open','In Progress','Completed','Cancelled') DEFAULT 'Open',
  PRIMARY KEY (`JobID`),
  KEY `FK_Job_Vehicle` (`VIN`),
  KEY `FK_Job_Workshop` (`WorkshopID`),
  KEY `FK_Job_Alert` (`AlertID`),
  CONSTRAINT `FK_Job_Alert` FOREIGN KEY (`AlertID`) REFERENCES `predictivealert` (`AlertID`),
  CONSTRAINT `FK_Job_Vehicle` FOREIGN KEY (`VIN`) REFERENCES `vehicle` (`VIN`),
  CONSTRAINT `FK_Job_Workshop` FOREIGN KEY (`WorkshopID`) REFERENCES `workshop` (`WorkshopID`),
  CONSTRAINT `maintenancejob_chk_1` CHECK ((`DowntimeHours` >= 0)),
  CONSTRAINT `maintenancejob_chk_2` CHECK ((`TotalCostVND` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=348 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

