--
-- Table structure for table `safetyevent`
--

DROP TABLE IF EXISTS `safetyevent`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `safetyevent` (
  `EventID` int NOT NULL AUTO_INCREMENT,
  `EventTimestamp` datetime NOT NULL,
  `VIN` varchar(17) NOT NULL,
  `DriverID` int NOT NULL,
  `DepotID` int NOT NULL,
  `EventTypeID` int NOT NULL,
  `SeverityID` int NOT NULL,
  `Odometer` int DEFAULT NULL,
  `ReviewStatus` enum('Pending','Reviewed') DEFAULT 'Pending',
  PRIMARY KEY (`EventID`),
  KEY `FK_Event_Vehicle` (`VIN`),
  KEY `FK_Event_Driver` (`DriverID`),
  KEY `FK_Event_Depot` (`DepotID`),
  KEY `FK_Event_Type` (`EventTypeID`),
  KEY `FK_Event_Severity` (`SeverityID`),
  CONSTRAINT `FK_Event_Depot` FOREIGN KEY (`DepotID`) REFERENCES `depot` (`DepotID`),
  CONSTRAINT `FK_Event_Driver` FOREIGN KEY (`DriverID`) REFERENCES `driver` (`DriverID`),
  CONSTRAINT `FK_Event_Severity` FOREIGN KEY (`SeverityID`) REFERENCES `severity` (`SeverityID`),
  CONSTRAINT `FK_Event_Type` FOREIGN KEY (`EventTypeID`) REFERENCES `eventtype` (`EventTypeID`),
  CONSTRAINT `FK_Event_Vehicle` FOREIGN KEY (`VIN`) REFERENCES `vehicle` (`VIN`),
  CONSTRAINT `safetyevent_chk_1` CHECK ((`Odometer` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=4861 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

