--
-- Table structure for table `vehicleassignment`
--

DROP TABLE IF EXISTS `vehicleassignment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vehicleassignment` (
  `AssignmentID` int NOT NULL AUTO_INCREMENT,
  `VIN` varchar(17) NOT NULL,
  `DriverID` int NOT NULL,
  `DepotID` int NOT NULL,
  `StartDate` date NOT NULL,
  `EndDate` date DEFAULT NULL,
  `AssignmentStatus` enum('Active','Completed','Cancelled') DEFAULT 'Active',
  PRIMARY KEY (`AssignmentID`),
  UNIQUE KEY `UQ_Vehicle_StartDate` (`VIN`,`StartDate`),
  KEY `FK_Assignment_Driver` (`DriverID`),
  KEY `FK_Assignment_Depot` (`DepotID`),
  CONSTRAINT `FK_Assignment_Depot` FOREIGN KEY (`DepotID`) REFERENCES `depot` (`DepotID`),
  CONSTRAINT `FK_Assignment_Driver` FOREIGN KEY (`DriverID`) REFERENCES `driver` (`DriverID`),
  CONSTRAINT `FK_Assignment_Vehicle` FOREIGN KEY (`VIN`) REFERENCES `vehicle` (`VIN`),
  CONSTRAINT `vehicleassignment_chk_1` CHECK (((`EndDate` is null) or (`EndDate` > `StartDate`)))
) ENGINE=InnoDB AUTO_INCREMENT=1109 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

